/* ==UserStyle==
@name Vikunja Catppuccin
@namespace github.com/catppuccin/userstyles/styles/vikunja
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/vikunja
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/vikunja/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Avikunja
@description Soothing pastel theme for Vikunja
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("try.vikunja.io") {
  :root.dark {
    #catppuccin(@darkFlavor);
  }
  :root.light {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    #hslbreakdown(@color, @item) {
      --@{item}-h: hue(@color) !important;
      --@{item}-s: saturation(@color) !important;
      --@{item}-l: lightness(@color) !important;
      --@{item}-light-l: lightness(@color) !important;
      --@{item}-dark-l: lightness(@color) !important;
      --@{item}-invert-l: lightness(@color) !important;
    }

    #hslbreakdown(@accent, primary);
    --grey-100-hsl: hue(@mantle) saturation(@mantle) lightness(@mantle);
    --site-background: @mantle;
    --content-heading-color: @text;
    --card-header-color: @text;
    --card-color: @text;
    --body-color: @text;
    --label-color: @text;
    --strong-color: @text;
    --primary: @accent;
    --primary-invert: @base;
    --switch-view-color: @base;
    --input-background-color: @base;
    --input-icon-color: @text;
    --table-row-hover-background-color: @mantle;
    --table-head-cell-color: @text;
    --input-border-color: @overlay0;
    --link-hover: @accent;
    --white: @base;
    --grey: @overlay0;
    --card-content-background-color: @base;
    --success: @green;
    --danger: @red;
    --warning: @yellow;
    --text: @text;
    --text-strong: @text;
    --button-text-hover-background-color: @base;
    --table-striped-row-even-background-color: @mantle;
    --code-background: @mantle;
    --code: @text;

    body,
    div#app,
    header,
    aside.menu-container,
    footer.card-footer {
      background: @mantle !important;
    }

    svg.llama-cool > circle,
    svg.logo > path[fill="#196aff"] {
      fill: @accent;
    }

    svg.logo,
    h1,
    .action-heading,
    .subtitle a,
    .project-menu-title {
      color: @text !important;
    }

    p.nothing,
    .has-text-grey-light {
      color: @subtext0 !important;
    }

    h1.title.task-id,
    div.detail-title,
    div.detail-title span {
      color: @overlay0;
    }

    button {
      box-shadow: none !important;
    }

    button.is-danger {
      color: @red !important;
      background: none;

      &:hover {
        background: @red !important;
        color: @surface0 !important;
      }

      &:active {
        background: darken(@red, 10%) !important;
        color: @surface0 !important;
      }
    }

    .has-text-danger {
      --has-text-hover-color: @red;
    }

    button.is-success {
      color: @green;

      &:hover {
        background: @green !important;
        color: @surface0 !important;
      }

      &:active {
        background: darken(@green, 10%) !important;
      }
    }

    .base-button.is-primary {
      color: @base;

      &:hover {
        background: @accent;
      }

      &:active {
        background: darken(@accent, 10%);
      }

      span.icon {
        color: @base !important;
      }
    }

    button.base-button:not(.is-primary) {
      color: @text;
    }

    div.action-buttons > button:hover,
    button.search-result-button:hover,
    .button.is-text:active,
    .single-task:hover {
      background: @mantle;
    }

    p.is-editor-empty::before {
      color: @overlay0;
    }

    header > button.base-button.menu-button::before,
    header > button.base-button.menu-button::after {
      background: @text;
    }

    .menu .menu-list {
      li > a,
      li > a > span {
        color: @text;
      }
      li > a.router-link-active {
        color: @accent;
      }
      li:hover {
        background: @mantle;
      }
    }

    a.base-button.menu-bottom-link {
      color: @overlay0;

      &:hover {
        color: @overlay2;
      }
    }

    div.is-done {
      background: @green;
      color: @surface0;
    }

    div.tiptap__editor {
      a {
        color: @accent;
      }
      pre,
      code {
        background: @surface0;
        color: @text;
      }
    }

    blockquote,
    hr {
      background: @surface0;
    }

    emoji-picker {
      --background: @surface0;
      --border-color: @overlay0;
      --button-hover-background: @overlay0;
      --input-border-color: @overlay0;
      scrollbar-color: @overlay0 @surface0 !important;
    }

    .reaction-button.current-user-has-reacted {
      border-color: @accent;
      background: fade(@accent, 30%);
    }

    p.created {
      color: @overlay0;
    }

    .progress-bar {
      --progress-bar-background-color: @crust;
      --progress-value-background-color: @accent;
    }

    .loader-container.is-loading::after {
      --loader-border-color: @accent;
    }

    /* Gantt */
    div.gantt-container {
      --grey-300: @surface0;
    }

    div.g-gantt-chart {
      .g-upper-timeunit,
      .g-timeunit {
        color: @text !important;
      }

      .g-timeunit .today {
        color: @surface0;
      }

      .g-gantt-row {
        background: @base;
      }

      div.g-gantt-bar {
        div.g-gantt-bar-label > div {
          color: @surface0;
        }

        .g-gantt-bar-handle-left,
        .g-gantt-bar-handle-right {
          background: darken(@accent, 10%);
        }
      }
    }

    /* Kaban */
    div.bucket-header,
    div.task-item,
    div.bucket-footer,
    div.bucket > button.base-button {
      background: @base;
    }

    div.task-item > .task {
      background: @mantle;

      span.priority-label {
        background: @surface0;
      }
    }

    /* Command Palette */
    span.result-title,
    div.active-cmd.tag {
      background: @base;
    }

    /* Keyboard Shortcuts modal */
    kbd {
      color: @text;
      border-color: @overlay0;
      background: @base;
    }

    div.message-wrapper > div.message.info {
      background: @base;
    }

    /* Popups */
    div.v-popper__inner {
      background: @mantle;
      color: @text;
    }

    div.v-popper__arrow-outer {
      border-color: @mantle;
    }

    .modal-mask {
      span,
      p,
      strong {
        color: @text !important;
      }
    }

    /* Vue Notifications */
    .vue-notification {
      color: @surface0 !important;
    }
    .vue-notification button {
      background: none;
      color: @overlay0 !important;
    }

    .vue-notification.success {
      background: @green;
      border-left-color: darken(@green, 5%);
    }
  }
}

